import { ValidationError } from '../errors/DomainError';

/** Value object: a requested quantity of one catalogue product. */
export class OrderLine {
  private constructor(
    readonly productId: string,
    readonly quantity: number,
  ) {}

  static of(productId: string, quantity: number): OrderLine {
    if (productId.trim() === '') {
      throw new ValidationError('Order line product id must not be empty');
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new ValidationError(`Quantity for product '${productId}' must be a positive integer`);
    }
    return new OrderLine(productId, quantity);
  }

  /** Combines lines for the same product so each product appears once per order. */
  static consolidate(lines: readonly OrderLine[]): OrderLine[] {
    const totals = new Map<string, number>();
    for (const line of lines) {
      totals.set(line.productId, (totals.get(line.productId) ?? 0) + line.quantity);
    }
    return [...totals].map(([productId, quantity]) => new OrderLine(productId, quantity));
  }
}

