import { ValidationError } from '../errors/DomainError';

/** The fulfilment lifecycle, in the only order an order may progress. */
export const FULFILMENT_SEQUENCE = ['placed', 'paid', 'packed', 'shipped', 'delivered'] as const;

export type FulfilmentStatus = (typeof FULFILMENT_SEQUENCE)[number];
export type OrderStatus = FulfilmentStatus | 'cancelled';

const ALL_STATUSES: readonly OrderStatus[] = [...FULFILMENT_SEQUENCE, 'cancelled'];

/** Statuses from which an order may still be cancelled (i.e. before it is shipped). */
const CANCELLABLE: readonly OrderStatus[] = ['placed', 'paid', 'packed'];

export function parseOrderStatus(value: string): OrderStatus {
  const match = ALL_STATUSES.find((status) => status === value);
  if (!match) {
    throw new ValidationError(`Unknown order status '${value}'. Expected one of: ${ALL_STATUSES.join(', ')}`);
  }
  return match;
}

/** Returns the single status that may follow the given one, or undefined at the end of the lifecycle. */
export function nextStatus(current: OrderStatus): FulfilmentStatus | undefined {
  if (current === 'cancelled') {
    return undefined;
  }
  return FULFILMENT_SEQUENCE[FULFILMENT_SEQUENCE.indexOf(current) + 1];
}

export function isCancellable(status: OrderStatus): boolean {
  return CANCELLABLE.includes(status);
}

